// The reader app. It asks OpenFeature for one flag and answers over HTTP.
// GET /flag?user=u-1&district=North  ->  {"flag":"wrench_disables_bike","user":"u-1","value":true}
// You do not edit this file. You edit flags/flagd.json.

import { FlagdProvider } from "@openfeature/flagd-provider";
import { OpenFeature } from "@openfeature/server-sdk";

const FLAG = "wrench_disables_bike";
const STARTED = new Date().toISOString(); // proves the reader was not restarted

// In the compose stack the reader syncs from the flagd container.
// With FLAGD_FILE set it reads the flag file directly, which is how the course check runs it.
const provider = process.env.FLAGD_FILE
  ? new FlagdProvider({ resolverType: "in-process", offlineFlagSourcePath: process.env.FLAGD_FILE })
  : new FlagdProvider({
      resolverType: "in-process",
      host: process.env.FLAGD_HOST ?? "flagd",
      port: 8015,
    });
await OpenFeature.setProviderAndWait(provider);
const client = OpenFeature.getClient();

Bun.serve({
  port: Number(process.env.PORT ?? 8080),
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== "/flag") return new Response("not found", { status: 404 });
    const user = url.searchParams.get("user") ?? "anonymous";
    const district = url.searchParams.get("district") ?? "none";
    const value = await client.getBooleanValue(FLAG, false, { targetingKey: user, district });
    return Response.json({ flag: FLAG, user, district, value, started: STARTED });
  },
});
console.log("reader is listening");
